// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title VaultManager
 * @notice Multi-token vault with fee-on-transfer token support
 * @dev Handles deposits/withdrawals with proper accounting for deflationary tokens
 */
contract VaultManager is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;

    struct VaultInfo {
        uint256 totalDeposited;
        uint256 totalShares;
        uint256 lastRebalanceTime;
        bool active;
    }

    struct UserPosition {
        uint256 shares;
        uint256 depositTimestamp;
        uint256 rewardDebt;
    }

    // Vault configuration
    mapping(address => VaultInfo) public vaults;
    mapping(address => mapping(address => UserPosition)) public positions;
    mapping(address => bool) public approvedTokens;
    mapping(address => uint256) public withdrawalFees; // basis points

    // Reward tracking
    uint256 public rewardPerShare;
    uint256 public constant PRECISION = 1e18;
    uint256 public constant MAX_FEE = 500; // 5%
    uint256 public constant MIN_LOCK_TIME = 1 days;

    // Emergency withdrawal signature tracking
    mapping(bytes32 => bool) public usedNonces;
    address public emergencySigner;

    event Deposited(address indexed token, address indexed user, uint256 amount, uint256 shares);
    event Withdrawn(address indexed token, address indexed user, uint256 amount, uint256 shares);
    event EmergencyWithdraw(address indexed token, address indexed user, uint256 amount);
    event VaultCreated(address indexed token);
    event RebalanceExecuted(address indexed token, uint256 newTotal);

    constructor(address _emergencySigner) {
        emergencySigner = _emergencySigner;
    }

    modifier onlyActiveVault(address token) {
        require(vaults[token].active, "Vault not active");
        _;
    }

    function createVault(address token, uint256 fee) external onlyOwner {
        require(!vaults[token].active, "Vault exists");
        require(fee <= MAX_FEE, "Fee too high");
        require(token != address(0), "Invalid token");

        vaults[token] = VaultInfo({
            totalDeposited: 0,
            totalShares: 0,
            lastRebalanceTime: block.timestamp,
            active: true
        });
        approvedTokens[token] = true;
        withdrawalFees[token] = fee;

        emit VaultCreated(token);
    }

    /**
     * @notice Deposit tokens into vault
     * @dev Handles fee-on-transfer tokens by measuring actual received amount
     */
    function deposit(address token, uint256 amount) external nonReentrant onlyActiveVault(token) {
        require(amount > 0, "Zero amount");

        uint256 balanceBefore = IERC20(token).balanceOf(address(this));
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        uint256 actualReceived = IERC20(token).balanceOf(address(this)) - balanceBefore;

        require(actualReceived > 0, "No tokens received");

        VaultInfo storage vault = vaults[token];
        uint256 sharesToMint;

        if (vault.totalShares == 0) {
            sharesToMint = actualReceived;
        } else {
            sharesToMint = (actualReceived * vault.totalShares) / vault.totalDeposited;
        }

        require(sharesToMint > 0, "Shares too small");

        vault.totalDeposited += actualReceived;
        vault.totalShares += sharesToMint;

        UserPosition storage pos = positions[token][msg.sender];
        pos.shares += sharesToMint;
        pos.depositTimestamp = block.timestamp;
        pos.rewardDebt = (pos.shares * rewardPerShare) / PRECISION;

        emit Deposited(token, msg.sender, actualReceived, sharesToMint);
    }

    /**
     * @notice Withdraw tokens from vault
     * @dev Calculates withdrawal amount based on share ratio with fee deduction
     */
    function withdraw(address token, uint256 shareAmount) external nonReentrant onlyActiveVault(token) {
        UserPosition storage pos = positions[token][msg.sender];
        require(pos.shares >= shareAmount, "Insufficient shares");
        require(shareAmount > 0, "Zero shares");
        require(block.timestamp >= pos.depositTimestamp + MIN_LOCK_TIME, "Lock period");

        VaultInfo storage vault = vaults[token];

        // Calculate proportional withdrawal amount
        uint256 withdrawAmount = (shareAmount * vault.totalDeposited) / vault.totalShares;

        // Apply withdrawal fee
        uint256 fee = (withdrawAmount * withdrawalFees[token]) / 10000;
        uint256 netAmount = withdrawAmount - fee;

        // Update state before transfer
        pos.shares -= shareAmount;
        vault.totalShares -= shareAmount;
        vault.totalDeposited -= withdrawAmount;

        // Transfer tokens
        IERC20(token).safeTransfer(msg.sender, netAmount);

        emit Withdrawn(token, msg.sender, netAmount, shareAmount);
    }

    /**
     * @notice Emergency withdrawal with signature authorization
     * @dev Bypasses lock period but requires emergency signer approval
     * @param token The token to withdraw
     * @param nonce Unique nonce to prevent replay
     * @param signature Emergency signer's signature
     */
    function emergencyWithdraw(
        address token,
        bytes32 nonce,
        bytes calldata signature
    ) external nonReentrant onlyActiveVault(token) {
        require(!usedNonces[nonce], "Nonce used");

        bytes32 message = keccak256(abi.encodePacked(
            msg.sender,
            token,
            nonce,
            block.chainid,
            address(this)
        ));
        bytes32 ethSignedHash = message.toEthSignedMessageHash();
        address signer = ethSignedHash.recover(signature);
        require(signer == emergencySigner, "Invalid signature");

        usedNonces[nonce] = true;

        UserPosition storage pos = positions[token][msg.sender];
        uint256 shareAmount = pos.shares;
        require(shareAmount > 0, "No position");

        VaultInfo storage vault = vaults[token];
        uint256 withdrawAmount = (shareAmount * vault.totalDeposited) / vault.totalShares;

        pos.shares = 0;
        vault.totalShares -= shareAmount;
        vault.totalDeposited -= withdrawAmount;

        IERC20(token).safeTransfer(msg.sender, withdrawAmount);

        emit EmergencyWithdraw(token, msg.sender, withdrawAmount);
    }

    /**
     * @notice Rebalance vault accounting after yield accrual
     * @dev Called by authorized rebalancer to update totalDeposited
     */
    function rebalance(address token) external onlyOwner onlyActiveVault(token) {
        VaultInfo storage vault = vaults[token];
        require(block.timestamp >= vault.lastRebalanceTime + 1 hours, "Too soon");

        uint256 currentBalance = IERC20(token).balanceOf(address(this));
        vault.totalDeposited = currentBalance;
        vault.lastRebalanceTime = block.timestamp;

        emit RebalanceExecuted(token, currentBalance);
    }

    /**
     * @notice Transfer shares between users (internal accounting)
     * @dev Allows share transfer without moving underlying tokens
     */
    function transferShares(
        address token,
        address to,
        uint256 shareAmount
    ) external onlyActiveVault(token) {
        require(to != address(0), "Invalid recipient");
        require(to != msg.sender, "Self transfer");

        UserPosition storage fromPos = positions[token][msg.sender];
        require(fromPos.shares >= shareAmount, "Insufficient shares");

        fromPos.shares -= shareAmount;

        UserPosition storage toPos = positions[token][to];
        toPos.shares += shareAmount;
        toPos.depositTimestamp = block.timestamp;
    }

    /**
     * @notice Batch deposit across multiple vaults
     * @dev Gas-efficient multi-token deposit
     */
    function batchDeposit(
        address[] calldata tokens,
        uint256[] calldata amounts
    ) external nonReentrant {
        require(tokens.length == amounts.length, "Length mismatch");
        require(tokens.length <= 10, "Too many tokens");

        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            uint256 amount = amounts[i];

            require(vaults[token].active, "Vault not active");
            require(amount > 0, "Zero amount");

            uint256 balanceBefore = IERC20(token).balanceOf(address(this));
            IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
            uint256 actualReceived = IERC20(token).balanceOf(address(this)) - balanceBefore;

            VaultInfo storage vault = vaults[token];
            uint256 sharesToMint;

            if (vault.totalShares == 0) {
                sharesToMint = actualReceived;
            } else {
                sharesToMint = (actualReceived * vault.totalShares) / vault.totalDeposited;
            }

            vault.totalDeposited += actualReceived;
            vault.totalShares += sharesToMint;

            UserPosition storage pos = positions[token][msg.sender];
            pos.shares += sharesToMint;
            pos.depositTimestamp = block.timestamp;
        }
    }

    /**
     * @notice Get user's withdrawable amount for a token
     */
    function getWithdrawableAmount(address token, address user) external view returns (uint256) {
        UserPosition storage pos = positions[token][user];
        VaultInfo storage vault = vaults[token];

        if (vault.totalShares == 0) return 0;

        uint256 grossAmount = (pos.shares * vault.totalDeposited) / vault.totalShares;
        uint256 fee = (grossAmount * withdrawalFees[token]) / 10000;
        return grossAmount - fee;
    }
}
